INSERT INTO feature VALUES('constructor-namespacing','modules','Constructor names namespaced by family',NULL,'partial','ordinary',NULL,'A constructor is named through its family, `Family.Constructor`, in a pattern and in a value, and bare where its name resolves to it; two data families of one source may share a constructor name, each named through its family, and a bare name that more than one family declares is refused `AmbiguousConstructor`, naming two of them, as a bare name two imports bind is refused `ImportShadows`; a multi-output constructor''s port is `Family.Constructor(e).l`, matched as `Family.Constructor(x).l`, and its record `Family.Constructor(e)`; a capitalised name the data family lacks is refused as its unknown member. The printer writes a constructor of `Theory` qualified where the source''s own constructor takes its bare name, and a constructor whose name another family shares qualified. The choice of a shared bare name by the scrutinee''s or the expected type, and a data block''s rule terms naming its constructors qualified, are owed.','surface-grammar surface-lowering surface-diagnostics','corpus/model/desc/theory-constructor-qualified.gandr corpus/pathological/desc/theory-constructor-qualified.gandr crates/surface-lowering/src/lower/native/fixture/qualified_ports.gandr corpus/model/data/constructor-shared-name.gandr corpus/model/data/constructor-imported-bare.gandr corpus/pathological/data/constructor-shared-bare.gandr corpus/pathological/data/constructor-shared-imported.gandr corpus/pathological/data/constructor-two-imports.gandr','corpus/ledger/features/constructor-namespacing.gandr','#354 #5691 #4293');
